// Kind of BSD slot `number` in the reference XNU for `darwin_release`.
[[nodiscard]] constexpr BsdSlot bsd_slot(
    std::string_view darwin_release, std::uint32_t number)
{
    for (const auto& release : detail::releases) {
        if (release.darwin_release != darwin_release)
            continue;
        if (std::binary_search(release.calls.begin(), release.calls.end(), number))
            return BsdSlot::Call;
        if (std::binary_search(release.enosys.begin(), release.enosys.end(), number))
            return BsdSlot::Enosys;
        if (std::binary_search(release.firmware.begin(), release.firmware.end(), number))
            return BsdSlot::FirmwareStub;
        return BsdSlot::Nosys;
    }
    return BsdSlot::UnknownRelease;
}

// True when the reference kernel would not raise SIGSYS for `number`.
[[nodiscard]] constexpr bool bsd_slot_defined(
    std::string_view darwin_release, std::uint32_t number)
{
    const auto slot = bsd_slot(darwin_release, number);
    return slot == BsdSlot::Call || slot == BsdSlot::Enosys ||
        slot == BsdSlot::FirmwareStub;
}

// True when the reference tag, the next newer tag and the release's firmware
// libsystem all lack `number`: the kernel answers it with nosys().
[[nodiscard]] constexpr bool bsd_slot_gated(
    std::string_view darwin_release, std::uint32_t number)
{
    for (const auto& release : detail::releases) {
        if (release.darwin_release != darwin_release)
            continue;
        return number / 32U < release.gated.size() &&
            ((release.gated[number / 32U] >> (number % 32U)) & 1U) != 0U;
    }
    return false;
}

